#!/bin/bash
source "$(dirname "$0")/lib.sh"; NL=$'\n'; export LC_ALL=C; SC=0
UP=$(apt list --upgradable 2>/dev/null | grep -c upgradable); SU=$(apt list --upgradable 2>/dev/null | grep -ci security)
ST=/var/lib/apt/periodic/update-success-stamp; [ -f $ST ] && AG=$(( ($(date +%s)-$(stat -c %Y $ST))/86400 )) || AG=-1
if [ $SU -gt 0 ]; then MJ="⚠️ $SU mise(s) à jour de sécurité en attente ($UP au total).${NL}   Pourquoi : une mise à jour de sécurité bouche une faille déjà connue ; tant qu'elle n'est pas installée, la faille reste utilisable par un attaquant."; SC=2
elif [ $UP -gt 0 ]; then MJ="🟡 Aucune mise à jour de sécurité en attente, mais $UP mise(s) à jour ordinaires.${NL}   Pourquoi : elles apportent des corrections et améliorations, moins urgentes."; [ $SC -lt 1 ] && SC=1
else MJ="✅ Tout est à jour.${NL}   Pourquoi : aucune faille connue n'est laissée ouverte par un logiciel ancien."; fi
[ $AG -ge 7 ] && { MJ="$MJ${NL}   ⚠️ La liste des mises à jour date de $AG jours : elle n'est peut-être plus à jour, lancez « sudo apt update »."; [ $SC -lt 1 ] && SC=1; }
[ $AG -ge 0 ] && [ $AG -lt 7 ] && MJ="$MJ${NL}   Dernière vérification : il y a $AG jour(s)."
dpkg -s unattended-upgrades >/dev/null 2>&1 && AU="✅ Mises à jour de sécurité automatiques : installées.${NL}   Pourquoi : elles se font toutes seules, sans que vous ayez à y penser." || AU="⚪ Mises à jour automatiques : non installées.${NL}   Pourquoi : il faut donc les lancer vous-même régulièrement (paquet unattended-upgrades pour automatiser)."
[ -f /var/run/reboot-required ] && { RB="⚠️ Un redémarrage est nécessaire.${NL}   Pourquoi : une mise à jour (souvent du noyau) n'est active qu'après redémarrage ; sans cela, la faille corrigée reste ouverte."; [ $SC -lt 1 ] && SC=1; } || RB="✅ Aucun redémarrage en attente."
FW=""; for s in ufw nftables firewalld; do systemctl is-active --quiet $s 2>/dev/null && FW="$s"; done
grep -qiE "^ENABLED=yes" /etc/ufw/ufw.conf 2>/dev/null && FW=ufw
[ -n "$FW" ] && PF="✅ Pare-feu actif ($FW).${NL}   Pourquoi : c'est un videur à l'entrée : il refuse les connexions venues de l'extérieur que vous n'avez pas autorisées." || { PF="🟡 Aucun pare-feu détecté (ufw, nftables, firewalld).${NL}   Pourquoi : sans videur, toute porte ouverte (voir ci-dessous) est joignable depuis votre réseau. Si aucune porte n'est ouverte, le risque reste faible. Installation simple : sudo apt install ufw && sudo ufw enable."; }
pd(){ case $1 in 3000) echo "Open WebUI : interface de chat avec des modèles d'IA, lancée par Docker.";; 22) echo "Accès à distance (SSH) : permet de piloter l'ordinateur depuis un autre appareil.";; 631) echo "Impression (CUPS).";; 80|443|8080) echo "Serveur de sites web.";; 8765) echo "Le serveur DMP, qui affiche ces pages.";; 3306) echo "Base de données MySQL/MariaDB.";; 5432) echo "Base de données PostgreSQL.";; 25|587) echo "Service de courrier interne (ici Postfix) : il distribue les messages que le système s'envoie à lui-même, comme les alertes des tâches programmées. Il n'envoie rien sur internet.";; 445|139) echo "Partage de fichiers Windows (Samba).";; 53) echo "Annuaire des noms de sites (DNS) local.";; *) echo "Programme qui attend des connexions sur ce numéro.";; esac; }
EXP=0; LOC=0; PT=""
while read -r a; do p=${a##*:}; h=${a%:*}
 case "$h" in 127.*|"[::1]"|::1) LOC=$((LOC+1)); PT="$PT${NL}🔒 Porte $p : interne à l'ordinateur${NL}   • Rôle : $(pd $p)${NL}   • Pourquoi sans risque : elle n'écoute que cet ordinateur, personne d'autre ne peut s'y connecter.${NL}";;
 *) EXP=$((EXP+1)); PT="$PT${NL}🚪 Porte $p : joignable depuis le réseau${NL}   • Rôle : $(pd $p)${NL}   • Pourquoi à surveiller : n'importe quel appareil de votre réseau peut tenter de s'y connecter. Si vous n'en avez pas besoin, fermez-la en arrêtant le service.${NL}";; esac
done < <(ss -tlnH 2>/dev/null | awk '{print $4}' | sort -u)
[ $EXP -gt 3 ] && SC=2; [ $EXP -gt 0 ] && [ $SC -lt 1 ] && SC=1
SSH=""; if systemctl is-active --quiet ssh 2>/dev/null || systemctl is-active --quiet sshd 2>/dev/null; then PR=$(grep -hiE '^\s*PermitRootLogin' /etc/ssh/sshd_config /etc/ssh/sshd_config.d/* 2>/dev/null | tail -1 | awk '{print $2}'); case "$PR" in yes) SSH="🔴 Accès distant actif, connexion directe du compte administrateur AUTORISÉE.${NL}   Pourquoi dangereux : tout le monde connaît le nom « root » ; un pirate n'a plus qu'à trouver le mot de passe. Mettez PermitRootLogin no."; SC=2;; *) SSH="🟡 Accès distant (SSH) actif.${NL}   Pourquoi : utile si vous en avez besoin. Sinon, désactivez-le : une porte fermée ne peut pas être forcée.";; esac; else SSH="✅ Accès distant (SSH) arrêté.${NL}   Pourquoi : personne ne peut se connecter à distance à cet ordinateur."; fi
AA=$(cat /sys/module/apparmor/parameters/enabled 2>/dev/null); [ "$AA" = Y ] && AP="✅ AppArmor actif.${NL}   Pourquoi : il enferme chaque programme dans un cadre ; un programme piraté ne peut pas toucher au reste." || AP="⚪ AppArmor inactif.${NL}   Pourquoi : c'est une protection supplémentaire non utilisée ; cela ne signifie pas un risque immédiat."
LG=$(last -n 60 -w 2>/dev/null | grep -v -e '^$' -e wtmp -e reboot | head -5 | sed 's/^/   • /')
O="La sécurité, c'est comme fermer sa maison : on vérifie les serrures (mises à jour), le videur (pare-feu), les portes laissées ouvertes (ports) et qui est entré récemment. Pourquoi cette page : la plupart des intrusions passent par une faille déjà corrigée mais non installée, ou par une porte inutilement ouverte.${NL}${NL}🛠️ Mises à jour${NL}$MJ${NL}$AU${NL}$RB${NL}${NL}🧱 Pare-feu${NL}$PF${NL}${NL}🚪 Portes (ports) en écoute : $EXP joignable(s) depuis le réseau, $LOC interne(s)${NL}   Pourquoi : un « port » est une porte numérotée par laquelle un programme reçoit des connexions. Plus il y a de portes joignables depuis l'extérieur, plus il y a de points d'entrée possibles.$PT${NL}🔑 Accès à distance${NL}$SSH${NL}${NL}🛡️ Protection des programmes${NL}$AP${NL}${NL}👤 5 dernières connexions à cet ordinateur${NL}   Pourquoi : repérer une connexion que vous ne reconnaissez pas.${NL}${LG:-   • Historique non disponible}"
case $SC in 0) R="Système bien protégé"; X="Aucune mise à jour en attente, aucune porte inutilement ouverte, rien à signaler : les principales entrées sont fermées. Gardez l'habitude d'installer les mises à jour chaque semaine.";; 1) R="Protégé, quelques points à améliorer"; X="Rien de grave : le système n'est pas en danger immédiat, mais certains points ci-dessus (mises à jour ordinaires, pare-feu absent, porte joignable, redémarrage) rendraient la protection plus solide. Traitez-les dans l'ordre affiché.";; *) R="Failles à corriger rapidement"; X="Un point sérieux est signalé (mise à jour de sécurité en attente, trop de portes ouvertes ou accès administrateur à distance). Corrigez-le en priorité : sudo apt update && sudo apt upgrade.";; esac
export X; j "Cette page vérifie que les portes de votre ordinateur sont bien fermées : mises à jour de sécurité, pare-feu, portes ouvertes, accès à distance." "$O" "$R" "apt, ss, systemctl, last (DMP uniquement)"
